const std = @import("std");

const print = std.debug.print;
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;
const VerificationResultMap = std.StringHashMap(VerificationResult);
const ProofCacheMap = std.StringHashMap([]const u8);

pub const PropertyType = enum {
    safety,
    liveness,
    invariant,
    termination,
    memory_safety,
    thread_safety,
    functional_correctness,
    performance,
    resource_bound,
    information_flow,
};

pub const Priority = enum {
    critical,
    high,
    medium,
    low,
};

pub const FormalVerificationConfig = struct {
    proof_checking_enabled: bool = true,
    theorem_proving_enabled: bool = true,
    property_verification: bool = true,
    invariant_checking: bool = true,
    termination_analysis: bool = true,
    memory_safety_proofs: bool = true,
    thread_safety_proofs: bool = true,
    functional_correctness: bool = true,
    dependent_type_checking: bool = true,
    linear_type_checking: bool = true,
    affine_type_checking: bool = true,
    ownership_verification: bool = true,
    borrowing_verification: bool = true,
    lifetime_analysis: bool = true,
    effect_verification: bool = true,
    resource_analysis: bool = true,
    automated_proof_search: bool = true,
    tactic_proof_generation: bool = true,
    smt_solver_integration: bool = true,
    model_checking: bool = true,
    abstract_interpretation: bool = true,
    symbolic_execution: bool = true,
    parallel_verification: bool = true,
    incremental_verification: bool = true,
    proof_caching: bool = true,
    lazy_verification: bool = true,
