};

pub const VerificationResult = struct {
    passed: bool,
    proof_found: bool,
    counterexample_found: bool,
    timeout_occurred: bool,
    error_message: ?[]const u8,
    proof_trace: ?[]const u8,
    verification_time_ms: u64,
    proof_size: u64,
    smt_queries_used: u32,

    pub fn isValid(self: VerificationResult) bool {
        return self.passed and self.proof_found and !self.counterexample_found;
    }

    pub fn hasError(self: VerificationResult) bool {
        return self.error_message != null or self.timeout_occurred;
    }
};

pub const Property = struct {
    name: []const u8,
    description: []const u8,
    formula: []const u8,
    property_type: PropertyType,
    priority: Priority,
};

