    pub fn deinit(self: *Self) void {
        if (self.agda_interface) |agda| {
            self.allocator.destroy(agda);
            self.agda_interface = null;
        }
        if (self.idris_interface) |idris| {
            self.allocator.destroy(idris);
            self.idris_interface = null;
        }
        if (self.coq_interface) |coq| {
            self.allocator.destroy(coq);
            self.coq_interface = null;
        }
        if (self.lean_interface) |lean| {
            self.allocator.destroy(lean);
            self.lean_interface = null;
        }
        if (self.z3_solver) |z3| {
            self.allocator.destroy(z3);
            self.z3_solver = null;
        }
        if (self.cvc5_solver) |cvc5| {
            self.allocator.destroy(cvc5);
            self.cvc5_solver = null;
        }
        if (self.vampire_solver) |vampire| {
            self.allocator.destroy(vampire);
            self.vampire_solver = null;
        }

        var prop_it = self.properties.items;
        for (prop_it) |p| {
            self.allocator.free(p.name);
            self.allocator.free(p.description);
            self.allocator.free(p.formula);
        }
        self.properties.deinit();

        var cache_it = self.proof_cache.iterator();
        while (cache_it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            self.allocator.free(entry.value_ptr.*);
        }
        self.proof_cache.deinit();

        var result_it = self.verification_results.iterator();
        while (result_it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
        }
        self.verification_results.deinit();

        self.initialized = false;
        print("Formalis verifikacios rendszer leallitva\n", .{});
    }

