    pub fn verifyMemorySafety(self: *Self) !bool {
        if (!self.initialized) return error.VerifierNotInitialized;
        var all_passed = true;
        for (self.properties.items) |property| {
            if (property.property_type == .memory_safety) {
                const result = try self.verifyProperty(property);
                if (!result.isValid()) {
