    pub fn verifyProperty(self: *Self, property: Property) !VerificationResult {
        if (!self.initialized) return error.VerifierNotInitialized;
        const start_time = std.time.milliTimestamp();

        if (self.config.proof_caching) {
            if (self.proof_cache.get(property.name)) |cached_proof| {
                self.cache_hits += 1;
                return VerificationResult{
                    .passed = true,
                    .proof_found = true,
                    .counterexample_found = false,
                    .timeout_occurred = false,
                    .error_message = null,
                    .proof_trace = cached_proof,
                    .verification_time_ms = 0,
                    .proof_size = cached_proof.len,
                    .smt_queries_used = 0,
                };
            }
        }

        self.cache_misses += 1;

        var result = VerificationResult{
            .passed = false,
            .proof_found = false,
            .counterexample_found = false,
            .timeout_occurred = false,
            .error_message = null,
            .proof_trace = null,
            .verification_time_ms = 0,
            .proof_size = 0,
            .smt_queries_used = 0,
        };

        var verification_successful = false;

        if (!verification_successful and self.config.theorem_proving_enabled and self.config.proof_checking_enabled) {
            verification_successful = try self.tryProofAssistantVerification(property, &result);
        }

        if (!verification_successful and self.config.smt_solver_integration) {
            verification_successful = try self.trySMTVerification(property, &result);
        }

        if (!verification_successful and self.config.model_checking) {
            verification_successful = try self.tryModelChecking(property, &result);
        }

        if (!verification_successful and self.config.abstract_interpretation) {
            verification_successful = try self.tryAbstractInterpretation(property, &result);
        }

        if (!verification_successful and self.config.symbolic_execution) {
            verification_successful = try self.trySymbolicExecution(property, &result);
        }

        result.verification_time_ms = @intCast(std.time.milliTimestamp() - start_time);

        const result_key = try self.allocator.dupe(u8, property.name);
        try self.verification_results.put(result_key, result);

        self.total_properties_verified += 1;
        self.total_verification_time_ms += result.verification_time_ms;

        if (result.isValid()) {
            self.successful_verifications += 1;
            self.total_proofs_generated += 1;
            if (self.config.proof_caching) {
                if (result.proof_trace) |proof_slice| {
                    const cached_name = try self.allocator.dupe(u8, property.name);
                    const cached_proof = try self.allocator.dupe(u8, proof_slice);
                    try self.proof_cache.put(cached_name, cached_proof);
                }
            }
            print("Tulajdonsag verifikacio sikeres: {s} ({} ms)\n", .{ property.name, result.verification_time_ms });
        } else {
            self.failed_verifications += 1;
            print("Tulajdonsag verifikacio sikertelen: {s} ({} ms)\n", .{ property.name, result.verification_time_ms });
        }

        return result;
    }

