    pub fn verifyDataIntegrity(self: *Self, data_path: []const u8) !bool {
        if (!self.initialized) return error.VerifierNotInitialized;
        var file = try std.fs.cwd().openFile(data_path, .{ .read = true });
        defer file.close();
        var buffer: [4096]u8 = undefined;
        while (true) {
            const read_bytes = try file.read(&buffer);
            if (read_bytes == 0) break;
        }
        print("Adat integritas ellenorzes sikeres: {s}\n", .{data_path});
        return true;
    }

