    pub fn addProperty(self: *Self, property: Property) !void {
        if (!self.initialized) return error.VerifierNotInitialized;
        const name = try self.allocator.dupe(u8, property.name);
        const description = try self.allocator.dupe(u8, property.description);
        const formula = try self.allocator.dupe(u8, property.formula);
        const owned = Property{
            .name = name,
            .description = description,
            .formula = formula,
            .property_type = property.property_type,
            .priority = property.priority,
        };
        try self.properties.append(owned);
        print("Tulajdonsag hozzadva: {s}\n", .{property.name});
    }

    pub fn getStatistics(self: *const Self) VerificationStatistics {
        const total = self.total_properties_verified;
        const avg: u64 = if (total > 0) self.total_verification_time_ms / total else 0;
        const cache_total: u64 = self.cache_hits + self.cache_misses;
        const cache_rate: f64 = if (cache_total > 0)
            @as(f64, @floatFromInt(self.cache_hits)) / @as(f64, @floatFromInt(cache_total))
        else
            0.0;
        const success_rate: f64 = if (total > 0)
            @as(f64, @floatFromInt(self.successful_verifications)) / @as(f64, @floatFromInt(total))
        else
            0.0;

        return VerificationStatistics{
            .total_properties = self.properties.items.len,
            .properties_verified = self.total_properties_verified,
            .successful_verifications = self.successful_verifications,
            .failed_verifications = self.failed_verifications,
            .total_proofs_generated = self.total_proofs_generated,
            .total_verification_time_ms = self.total_verification_time_ms,
            .average_verification_time_ms = avg,
            .cache_hit_rate = cache_rate,
            .success_rate = success_rate,
        };
    }

    pub fn printStatistics(self: *const Self) void {
        const stats = self.getStatistics();
        print("Formalis verifikacio statisztikak:\n", .{});
        print("Osszes tulajdonsag: {}\n", .{stats.total_properties});
        print("Verifikalt tulajdonsagok: {}\n", .{stats.properties_verified});
        print("Sikeres verifikaciok: {}\n", .{stats.successful_verifications});
        print("Sikertelen verifikaciok: {}\n", .{stats.failed_verifications});
        print("Generalalt bizonyitasok: {}\n", .{stats.total_proofs_generated});
        print("Osszes verifikacios ido: {} ms\n", .{stats.total_verification_time_ms});
        print("Atlagos verifikacios ido: {} ms\n", .{stats.average_verification_time_ms});
        print("Cache talalati arany: {d:.1}%\n", .{stats.cache_hit_rate * 100.0});
        print("Sikeres arany: {d:.1}%\n", .{stats.success_rate * 100.0});
    }
